import {getUser} from '@/lib/auth';import Link from 'next/link';export default async function Dashboard(){const {db,user}=await getUser();if(!user)return <p>Silakan <Link className="link" href="/login">login</Link>.</p>;const [{data:profile},{data:solves},{data:progress}]=await Promise.all([db.from('profiles').select('full_name').eq('id',user.id).single(),db.from('challenge_completions').select('awarded_points,challenge_id').eq('student_id',user.id),db.from('lesson_progress').select('lesson_id').eq('student_id',user.id)]);return <><h1>Dashboard Siswa</h1><p>Selamat datang, {profile?.full_name||user.email}</p><div className="gridcards"><div className="panel"><h2>Total XP</h2>{(solves||[]).reduce((s,x)=>s+x.awarded_points,0)}</div><div className="panel"><h2>CTF Selesai</h2>{solves?.length||0}</div><div className="panel"><h2>Materi Selesai</h2>{progress?.length||0}</div></div><div className="mt-6 flex gap-3"><Link className="btn" href="/learn">Belajar</Link><Link className="btn" href="/ctf">Kerjakan CTF</Link></div></>}